$("todayKeirin").onclick=()=>openMeetings();$("homeBtn").onclick=$("brand").onclick=()=>goHome();$("headerBack").onclick=()=>goBack();$("venueSelectBtn").onclick=()=>openVenueSelection();$("raceSelectBtn").onclick=()=>openRaceSelection();$("reloadMeetings").onclick=()=>loadMeetings();$("bulkRefresh").onclick=()=>bulkRefreshRaceInfo();$("runScreening").onclick=()=>runPrimaryScreening();$("raceDate").onchange=e=>{state.date=e.target.value;loadMeetings()};$("tabToday").onclick=()=>setMeetingTab("today");$("tabScreening").onclick=()=>setMeetingTab("screening");$("tabBattle").onclick=()=>setMeetingTab("battle");$("tabVenues").onclick=()=>setMeetingTab("venues");$("predictBtn").onclick=()=>handleDetailPrimary();$("retryDetail").onclick=()=>handleDetailSecondary();$("backToDetail").onclick=()=>{renderDetail();show("detail")};$("checkResult").onclick=()=>checkResult();$("retryBtn").onclick=()=>state.retry?.();$("errorHome").onclick=()=>goHome();
