function renderOfficial(p){const race=p?.race;if(race){state.race={...state.race,scheduledStart:race.startTime||state.race?.scheduledStart||race.deadline||"",deadline:race.deadline||state.race?.deadline||race.startTime||"",raceCategory:race.raceCategory||state.race?.raceCategory||"standard",lineMode:race.lineMode||state.race?.lineMode||"official_line"};const scoredMap=new Map((p?.prediction?.scored||[]).map(x=>[Number(x.number),x]));$("participantCount").textContent=`${race.participants.length}名`;$("participants").innerHTML=race.participants.map(x=>{const scored=scoredMap.get(Number(x.number)),side=race.raceCategory==="girls"&&scored?girlsLeadLabel(scored):(displayParticipantRole(x)||x.className||x.prefecture||"");return `<div class="rider"><span class="riderNo">${x.number}</span><span><strong>${esc(x.name)}</strong><small>ID ${esc(x.registration||x.sourcePath||"公式車番")}</small></span><small>${esc(side)}</small></div>`}).join("");$("officialLine").textContent=lineText(race.participants,race.raceCategory,p?.prediction?.scored||[]);$("oddsStatus").textContent=p.odds?.ok?`3連単 ${Object.keys(p.odds.odds||{}).length}件`:"オッズ取得失敗";$("oddsStatus").className=`pill ${p.odds?.ok?"success":"warning"}`;$("detailNotice").innerHTML=p.warnings?.length?`<div class="notice">${p.warnings.map(esc).join(" / ")}</div>`:"";return}const saved=state.snapshot,participants=saved?.participants||[];if(saved&&participants.length){$("participantCount").textContent=`${participants.length}名`;const abilityMap=new Map((saved.abilitiesUsed||[]).map(x=>[Number(x.number),x]));$("participants").innerHTML=participants.map(x=>{const a=abilityMap.get(Number(x.number)),side=saved.targetRace?.raceCategory==="girls"&&a?girlsLeadLabel(a):(displayParticipantRole(x)||x.className||x.prefecture||"");return `<div class="rider"><span class="riderNo">${x.number}</span><span><strong>${esc(x.name)}</strong><small>ID ${esc(x.registration||x.sourcePath||"保存時車番")}</small></span><small>${esc(side)}</small></div>`}).join("");const hasLine=participants.some(x=>x.lineId||x.line);$("officialLine").textContent=hasLine?lineText(participants,saved.targetRace?.raceCategory,saved.abilitiesUsed||[]):"保存時のライン情報なし";const odds=saved.oddsSnapshot;$("oddsStatus").textContent=odds?.ok?`保存時3連単 ${Object.keys(odds.odds||{}).length}件`:"保存時オッズ";$("oddsStatus").className=`pill ${odds?.ok?"success":""}`;$("detailNotice").innerHTML='<div class="notice">保存済み予想を表示中です。再予想せずに買い目・根拠を確認できます。</div>';return}$("participantCount").textContent="未取得";$("participants").innerHTML='<p class="muted">出走選手は予想生成時に保存されます。</p>';$("officialLine").textContent="未取得";$("oddsStatus").textContent="オッズ未取得";$("detailNotice").innerHTML=""}

async function predict(){if(state.busy)return;const fixed={...state.race,key:raceKey(state.race)};state.busy=true;$("predictBtn").disabled=true;setLoading("予想を作成中","出走選手・公式ライン・3連単オッズを取得しています。");try{const result=await fetchAndSavePredictionForRace(fixed);state.payload=result.payload;state.race=result.race;state.snapshot=result.snapshot;renderOfficial(result.payload);renderHomeRecommendations();renderPrediction(result.snapshot)}catch(e){fail("予想の取得・保存に失敗",e,predict)}finally{state.busy=false;$("predictBtn").disabled=false}}
function renderPrediction(snapshot){state.snapshot=snapshot;const r=snapshot.targetRace;state.race={...state.race,...r};$("predictionTitle").textContent=`${r.venueName} ${r.raceNo}R`;$("recommendation").textContent=snapshot.noBet?"見送り":"買い目";$("predictionUpdated").textContent=formatTime(snapshot.createdAt);$("predictionSummary").innerHTML=metas([["買い目",`${snapshot.betSelections.length}点`],["締切",deadlineOf(r)||"未取得"]]);renderRatings($("predictionRatings"),snapshot);renderPurchaseControls(snapshot);renderBetGroups(snapshot);renderResult(snapshot.result);show("prediction")}
function renderPurchaseControls(snapshot){const panel=$("purchaseControls"),bets=snapshot.betSelections||[];if(!panel||snapshot.noBet||!bets.length){if(panel)panel.classList.add("hidden");return}const originalTotal=bets.reduce((sum,b)=>sum+(Number(b.stake)||0),0)||Math.max(1000,bets.length*100);const current=Math.max(0,Number(panel.dataset.budget)||originalTotal);const mode=panel.dataset.mode||"standard";const minimum=bets.length*100;const composite=calcCompositeOdds(bets);panel.innerHTML=`<div class="sectionHead"><h2>購入資金</h2><span class="pill">${bets.length}点</span></div><div class="fundingRow"><label>購入資金<input id="purchaseBudget" type="number" min="0" step="100" value="${current}"></label><label>配分<select id="allocationMode"><option value="standard"${mode==="standard"?" selected":""}>標準</option><option value="main"${mode==="main"?" selected":""}>本線厚め</option><option value="high"${mode==="high"?" selected":""}>高配当重視</option></select></label></div><div class="quickBudget">${[1000,1500,2000,3000].map(v=>`<button type="button" data-budget="${v}">${v.toLocaleString()}円</button>`).join("")}</div><div class="purchaseStats"><span>最低必要資金 <strong>${minimum.toLocaleString()}円</strong></span><span>合成オッズ <strong>${composite?`${composite.toFixed(2)}倍`:"未取得"}</strong></span></div>${current<minimum?`<div class="notice">自然買い目${bets.length}点 / 必要最低資金${minimum.toLocaleString()}円。${current.toLocaleString()}円では全点購入できません。買い目は自動で削りません。</div>`:""}`;panel.classList.remove("hidden");panel.dataset.budget=String(current);panel.dataset.mode=mode;$("purchaseBudget").oninput=e=>{panel.dataset.budget=String(Math.max(0,Number(e.target.value)||0));renderBetGroups(snapshot);renderPurchaseControls(snapshot)};$("allocationMode").onchange=e=>{panel.dataset.mode=e.target.value;renderBetGroups(snapshot);renderPurchaseControls(snapshot)};panel.querySelectorAll("[data-budget]").forEach(b=>b.onclick=()=>{panel.dataset.budget=b.dataset.budget;renderBetGroups(snapshot);renderPurchaseControls(snapshot)})}
function renderBetGroups(snapshot){const groups=[["本線","MAIN"],["押さえ","COVER"],["買える高配当","BUYABLE_HIGH"]],bets=snapshot.betSelections||[],panel=$("purchaseControls"),budget=Number(panel?.dataset.budget)||bets.reduce((s,b)=>s+(Number(b.stake)||0),0),mode=panel?.dataset.mode||"standard",stakes=allocatePreviewStakes(bets,budget,mode);$("betGroups").innerHTML=groups.map(([label,key])=>{const rows=bets.map((b,i)=>({b,i})).filter(x=>x.b.category===key);return rows.length?`<section class="betCard"><h3>${label}</h3><div class="betRows">${rows.map(({b,i})=>`<div class="betRow betRowSimple"><strong>${b.order.join("-")}</strong><span>${b.odds?`${Number(b.odds)}倍`:"オッズ確認待ち"}${stakes?` / ${Number(stakes[i]).toLocaleString()}円`:" / 配分不可"}</span></div>`).join("")}</div></section>`:""}).join("")||(snapshot.noBet?`<section class="card empty"><strong>見送り</strong><p>${esc(noBetReasonText(snapshot.noBetReason))}</p></section>`:'<section class="card empty">購入対象の買い目はありません。</section>')}
function allocatePreviewStakes(bets,budget,mode){const n=bets.length,min=n*100;if(!n||budget<min)return null;const base=bets.map(b=>Math.max(1,Number(b.stake)||100));const mul=bets.map(b=>mode==="main"?(b.category==="MAIN"?1.6:b.category==="BUYABLE_HIGH"?.8:1):mode==="high"?(b.category==="BUYABLE_HIGH"?1.6:b.category==="MAIN"?1:.9):1);const weights=base.map((v,i)=>v*mul[i]),extra=budget-min,total=weights.reduce((a,b)=>a+b,0)||n;let out=weights.map(w=>100+Math.floor((extra*w/total)/100)*100),used=out.reduce((a,b)=>a+b,0),remain=Math.floor((budget-used)/100);const order=weights.map((w,i)=>({w,i})).sort((a,b)=>b.w-a.w||a.i-b.i);for(let k=0;k<remain;k++)out[order[k%order.length].i]+=100;return out}
function calcCompositeOdds(bets){const valid=bets.map(b=>Number(b.odds)).filter(v=>Number.isFinite(v)&&v>0);if(!valid.length||valid.length!==bets.length)return null;const inv=valid.reduce((s,v)=>s+1/v,0);return inv>0?1/inv:null}

function renderBranchSelectionAudit(audit){const data=audit?.branchSelectionAudit;if(!data||!Array.isArray(data.rows)||!data.rows.length)return"";const priorityLabel={main:"本命展開",contender:"有力展開",sub:"別展開",risk:"リスク枝"};const rows=data.rows.map((branch,index)=>{const trace=Array.isArray(branch.scoreTrace)?branch.scoreTrace:[];const traceText=trace.slice(0,5).map(item=>`${esc(item.key)} ${fmtRatio(item.value)}×${fmtRatio(item.weight)}=${fmtRatio(item.contribution)}`).join(" / ");return `<div class="detailBet"><strong>${index+1}. ${esc(branch.label||branch.id||"不明")}　${esc(priorityLabel[branch.priority]||branch.priority||"-")}</strong><p>枝スコア ${fmtRatio(branch.score)} / 全枝比 ${fmtPct(branch.share)} / 首位比 ${fmtPct(branch.relativeToTop)}${branch.primaryLineId?` / ライン ${esc(branch.primaryLineId)}`:""}</p>${traceText?`<p class="muted">内訳: ${traceText}</p>`:""}</div>`}).join("");const tier=data.tiering||{};let basis;if(data.mainSelectionMode==="HIERARCHICAL_NATURAL_TIERS"){const main=(data.mainBranchLabels||[]).map(esc).join(" / ")||"なし";const contenders=(data.contenderBranchLabels||[]).map(esc).join(" / ")||"なし";const cut=Number.isFinite(tier.contenderCutGap)?` 有力展開と別展開の自然境界差 ${fmtRatio(tier.contenderCutGap)}。`:" 下位側に明確な自然境界がないため、無理に有力/別展開を2群化していません。";basis=`構造枝を全ライン横断で比較。最上位（同点時のみ複数）を本命展開とし、残りは隣接スコア差の分布から明確な下位境界がある場合だけ有力展開/別展開へ分離。固定90%や強制2群分割は不使用。本命: ${main} / 有力: ${contenders}。${cut}`}else{const split=data.adaptiveSplit||{};const gap=Number.isFinite(split.cutGap)?` / 境界差 ${fmtRatio(split.cutGap)}`:"";basis=data.topStructuredBranchLabel?`旧方式: 枝スコア分布の2群分割。主展開候補: ${(data.mainBranchLabels||[]).map(esc).join(" / ")||"なし"}${gap}。`:"構造枝の主展開候補なし。"}return `<h3>展開枝の事前評価</h3><div class="auditCallout"><strong>展開分類の基準</strong><p>${basis}</p></div><div class="detailGroup">${rows}</div>`}
function renderAdoptedTerminalAudit(audit){const rows=Array.isArray(audit?.adoptedTerminalAudit)?audit.adoptedTerminalAudit:[];if(!rows.length)return"";const priorityLabel={main:"本命展開",contender:"有力展開",sub:"別展開",risk:"リスク枝",unknown:"不明"};const tierCounts=audit.adoptedBranchTierCounts||{};const tierSummary=["main","contender","sub","risk"].filter(key=>Number(tierCounts[key]||0)>0).map(key=>`${priorityLabel[key]} ${tierCounts[key]}点`).join(" / ");const branchRows=Object.entries(audit.adoptedBranchCounts||{}).sort((a,b)=>b[1]-a[1]).map(([label,count])=>`<div class="abilityRow"><strong>${esc(label)}</strong><span>${count}件</span></div>`).join("");const terminalRows=rows.map(item=>{const r=item.decisionRatios||{};const ratios=`1着 ${fmtRatio(r.first)} / 2着 ${fmtRatio(r.second)} / 3着 ${fmtRatio(r.third)}`;const supportBranches=Array.isArray(item.supportBranches)?item.supportBranches:[];const supportRows=supportBranches.map((branch,index)=>`<div class="abilityRow"><strong>${index+1}. ${esc(branch.branchLabel||branch.branchId||"不明")}</strong><span>${esc(priorityLabel[branch.branchPriority]||branch.branchPriority||"-")} / 寄与 ${fmtRatio(branch.probability)} / 枝内適合 ${fmtRatio(branch.withinBranchFit)} / 枝強度 ${fmtRatio(branch.branchStrengthRatio)} / 加重 ${fmtRatio(branch.weightedSupport)}</span></div>`).join("");const dup=Array.isArray(item.duplicateSupportLabels)&&item.duplicateSupportLabels.length?`<p class="auditWarn">重複ラベル: ${item.duplicateSupportLabels.map(x=>`${esc(x.label)}×${x.count}`).join(" / ")}</p>`:"";const thirdAudit=item.thirdVariantGroupSize?`<p class="muted">3着独立支持: 群${item.thirdVariantGroupSize}件 / 首位比 ${fmtRatio(item.thirdVariantRelativeToBest)} / 群内確率質量 ${fmtRatio(item.thirdVariantConditionalShare)}${item.thirdVariantNaturalCutDetected?` / 自然境界差 ${fmtRatio(item.thirdVariantCutGap)}`:" / 明確な自然境界なし"}</p>`:"";const oddsAudit=item.highPayoutAttribute?`<p class="muted">高配当属性: ${esc(item.highPayoutAttributeLabel||"高配当")}（実オッズ評価済み・展開ランクは変更しない）</p>`:item.highPayoutCandidate?`<p class="muted">高配当候補: ${item.oddsEvaluationStatus==="ODDS_AVAILABLE"?"実オッズ評価済み":"オッズ待ち（買える高配当には未昇格）"}</p>`:"";const tier=item.dominantBranchTierLabel||priorityLabel[item.dominantBranchPriority]||"不明";return `<div class="detailBet"><strong>${esc(item.order)}　${esc(item.betClass||"")}</strong><p><b>展開ランク ${esc(tier)}</b> / ${esc(item.dominantBranchLabel||"由来枝不明")} / 枝適合 ${fmtRatio(item.branchFit)} / 枝内${item.branchRank??"-"}位 / 由来枝${item.branchSupport??0}（固有${item.uniqueSupportBranchCount??item.branchSupport??0}） / 加重支持 ${fmtRatio(item.weightedBranchSupport)}</p><p class="muted">${ratios}</p>${thirdAudit}${oddsAudit}${supportRows?`<details class="supportBranchAudit"><summary>支持枝を全部見る（${supportBranches.length}本）</summary><div class="abilityList">${supportRows}</div>${dup}</details>`:""}</div>`}).join("");return `<h3>採用終端の由来</h3>${tierSummary?`<div class="auditCallout"><strong>購入13点などの展開ランク内訳</strong><p>${esc(tierSummary)}</p><p class="muted">別展開・リスク枝も生成履歴には残します。ここは採用された買い目だけの内訳です。</p></div>`:""}${branchRows?`<div class="abilityList">${branchRows}</div>`:""}<div class="detailGroup">${terminalRows}</div>`}
function fmtRatio(value){const n=Number(value);return Number.isFinite(n)?n.toFixed(3):"-"}
function fmtPct(v){const n=Number(v);return Number.isFinite(n)?`${(n*100).toFixed(1)}%`:"-"}
function renderPredictionDetail(snapshot){const panel=$("predictionDetail"),ratingPanel=$("detailRatings");if(!panel)return;if(!snapshot){panel.classList.add("hidden");panel.innerHTML="";if(ratingPanel)ratingPanel.classList.add("hidden");return}renderRatings(ratingPanel,snapshot);const groups=[["本線","MAIN"],["押さえ","COVER"],["買える高配当","BUYABLE_HIGH"]];const betDetail=groups.map(([label,key])=>{const bets=(snapshot.betSelections||[]).filter(b=>b.category===key);if(!bets.length)return"";return `<div class="detailGroup"><h3>${label}</h3>${bets.map(b=>`<div class="detailBet"><strong>${b.order.join("-")}</strong>${b.branchLabel?`<p>${esc(b.branchLabel)}${b.reason?` / ${esc(b.reason)}`:""}</p>`:""}${b.evidenceSummary?`<p class="muted">${esc(b.evidenceSummary)}</p>`:""}</div>`).join("")}</div>`}).join("");const abilities=(snapshot.abilitiesUsed||[]).map(a=>`<div class="abilityRow"><strong>${a.number}番</strong><span>近況 ${fmtAbility(a.recentForm)} / 主導権 ${fmtAbility(a.startPower)} / まくり ${fmtAbility(a.sprintPower)} / 差し ${fmtAbility(a.finishPower)} / 追走 ${fmtAbility(a.trackingSkill)}</span></div>`).join("");const audit=snapshot.predictionOutput?.audit||{};const rejectLabels={FLAT_DISTRIBUTION:"分布が平坦",NO_DOMINANT_BRANCH:"支配展開なし",PROBABILITY_SUPPORT:"確率支持不足",THIRD_VARIANT_SUPPORT:"同一展開内の3着支持不足",SUB_ODDS_PENDING:"別展開・オッズ待ち",SUB_NO_VALUE:"別展開・妙味条件不成立",BRANCH_OR_POSITION_SUPPORT:"枝適合/着順支持不足",CLASS_RULE:"分類条件不成立",UNKNOWN:"その他"};const rejectRows=Object.entries(audit.rejectCodeCounts||{}).sort((a,b)=>b[1]-a[1]).map(([code,count])=>`<div class="abilityRow"><strong>${esc(rejectLabels[code]||code)}</strong><span>${count}件</span></div>`).join("");const auditDetail=Number.isFinite(audit.generatedTerminalCount)?`<details class="predictionAccordion" open><summary>購入採用監査を見る</summary><div class="accordionBody"><div class="abilityList"><div class="abilityRow"><strong>生成終端</strong><span>${audit.generatedTerminalCount}件</span></div><div class="abilityRow"><strong>確率評価済み</strong><span>${audit.probabilityEvaluatedTerminalCount??audit.terminalCount??0}件</span></div><div class="abilityRow"><strong>購入採用</strong><span>${audit.adoptedTerminalCount??audit.finalBetCount??0}件</span></div><div class="abilityRow"><strong>購入不採用</strong><span>${audit.rejectedTerminalCount??0}件</span></div></div>${rejectRows?`<h3>不採用理由</h3><div class="abilityList">${rejectRows}</div>`:""}${renderBranchSelectionAudit(audit)}${renderAdoptedTerminalAudit(audit)}<p class="muted">固定点数・枝内順位上限・確率比の一律足切りは使用していません。同一1-2着内の3着候補は独立支持の自然境界で購入再評価し、全終端自体は保持します。BUYABLE_HIGHは実オッズ確認後だけ使用します。</p></div></details>`:"";panel.innerHTML=`<div class="sectionHead"><div><small>保存済み予想の根拠</small><h2>予想詳細</h2></div><span class="pill">詳細</span></div>${auditDetail}<details class="predictionAccordion"><summary>展開・買い目の根拠を見る</summary><div class="accordionBody">${betDetail||'<p class="muted">購入候補はありません。</p>'}</div></details>${abilities?`<details class="predictionAccordion"><summary>選手別能力を見る</summary><div class="abilityList accordionBody">${abilities}</div></details>`:""}${renderStartPowerInputAudit(snapshot)}`;panel.classList.remove("hidden")}
function renderStartPowerInputAudit(snapshot){const rows=(snapshot.abilitiesUsed||[]).filter(a=>a.startPowerEvidence).map(a=>{const e=a.startPowerEvidence||{};const rawB=e.rawBackCount,rawH=e.rawHomeCount,starts=e.officialTotalStarts;const bRate=e.bFrequency,hRate=e.hFrequency,sb=e.shrunkBFrequency,sh=e.shrunkHFrequency;const confidence=({low:"低",medium:"中",high:"高"})[e.confidence]||e.confidence||"-";const status=e.missingInputs?.length?`欠損 ${e.missingInputs.join("/")}`:`信頼度 ${confidence}`;return `<div class="detailBet"><strong>${a.number}番　主導権 ${fmtAbility(a.startPower)}</strong><p>B ${fmtAuditNumber(rawB)} / H ${fmtAuditNumber(rawH)} / 出走 ${fmtAuditNumber(starts)}　${esc(status)}</p><p class="muted">B率 ${fmtAuditRate(bRate)} / H率 ${fmtAuditRate(hRate)} → 縮小後B ${fmtAuditRate(sb)} / 縮小後H ${fmtAuditRate(sh)} / B分位 ${fmtAbility(e.bPercentileScore)} / H分位 ${fmtAbility(e.hPercentileScore)} / latent ${fmtAbility(e.latentScore)}</p><p class="muted">カテゴリ ${esc(e.raceCategory||"-")} / prior ${fmtAuditNumber(e.priorStrength)} / startsQuality ${fmtRatio(e.startsQuality)}</p></div>`}).join("");return rows?`<details class="predictionAccordion"><summary>主導権の入力監査を見る</summary><div class="accordionBody"><p class="muted">数値を補正する画面ではなく、B/H入力から最終startPowerまでを確認する監査表示です。</p><div class="detailGroup">${rows}</div></div></details>`:""}
function hasUsableGirlsStartPower(a){const e=a?.startPowerEvidence;return Number.isFinite(Number(a?.startPower))&&Boolean(e)&&(!Array.isArray(e.missingInputs)||e.missingInputs.length===0)&&e.profileIdentityPassed!==false}
function girlsLeadLabel(a){return hasUsableGirlsStartPower(a)?`主導権 ${fmtAbility(a.startPower)}`:"主導権 保留"}
function fmtAuditNumber(v){const n=Number(v);return Number.isFinite(n)?String(Math.round(n*1000)/1000):"-"}
function fmtAuditRate(v){const n=Number(v);return Number.isFinite(n)?`${(n*100).toFixed(1)}%`:"-"}
function fmtAbility(v){return Number.isFinite(Number(v))?Number(v).toFixed(2):"-"}
function ratingOf(snapshot){return snapshot?.displayRatings||derivePredictionRatings(snapshot)}
function renderRatings(panel,snapshot){if(!panel)return;if(!snapshot){panel.classList.add("hidden");panel.innerHTML="";return}const r=ratingOf(snapshot),tone=r.verdictTone||"caution";panel.className=`card compact ratingPanel rating-${tone}`;panel.innerHTML=`<div class="sectionHead"><div><small>表示用評価</small><h2>レース評価</h2></div><span class="pill ratingVerdict rating-${tone}">${esc(r.verdict)}</span></div><div class="ratingGrid"><div class="ratingItem"><span>信頼度</span><strong>${starText(r.confidence)}</strong></div><div class="ratingItem"><span>展開集中度</span><strong>${starText(r.concentration)}</strong></div><div class="ratingItem"><span>コロがし適性</span><strong>${starText(r.rollover)}</strong></div><div class="ratingItem"><span>見送り判定</span><strong>${esc(r.verdict)}</strong></div></div><p class="ratingReason">${esc(r.reason||"")}</p><p class="muted ratingNote">既存の展開・購入監査から算出する表示用評価です。買い目の生成・採否ロジックは変更しません。</p>`;panel.classList.remove("hidden")}
function noBetReasonText(code){return({NO_TERMINALS:"展開候補を生成できませんでした。",FLAT_DISTRIBUTION_NO_SUPPORTED_CANDIDATE:"確率分布が平坦で、独立した展開根拠を持つ購入候補がありません。",BUDGET_BELOW_MINIMUM:"予算が最低購入単位を下回っています。",QUALITY_GATE:"データ品質基準を満たさないため購入を見送ります。",LINE_DATA_UNAVAILABLE:"公式ラインを確認できないため、通常の競輪予想としては購入判定を保留します。"})[code]||"購入価値を確認できないため見送ります。"}
async function checkResult(){if(state.busy||!state.snapshot)return;state.busy=true;setLoading("公式結果を確認中","レースIDを固定して確定着順と払戻を取得しています。");try{const r=state.snapshot.targetRace,p=await fetchOfficialResult(r);storeResultCache(r,p.result,p.checkedAt);if(isResultPending(p.result)){renderPrediction(state.snapshot);renderPendingResult();return}state.snapshot=attachResult(localStorage,state.snapshot.predictionSnapshotId,p.result);renderSaved();renderHomeRecommendations();renderPrediction(state.snapshot)}catch(e){fail("公式結果の取得・保存に失敗",e,checkResult)}finally{state.busy=false}}
function renderPendingResult(){$("resultPanel").className="card";$("resultPanel").innerHTML='<div class="resultMark">結果はまだ確定していません</div><p class="muted">公式結果の確定後にもう一度確認してください。</p><button id="retryPendingResult" class="secondary">再試行</button>';$('retryPendingResult').onclick=()=>checkResult()}
function renderResult(result){if(!result){$("resultPanel").classList.add("hidden");return}const cfg={hit:["○ 的中","resultHit"],miss:["✕ 不的中","resultMiss"],refund:["返還",""],cancelled:["中止",""]}[result.resultStatus]||[result.resultStatus,""];$("resultPanel").className=`card ${cfg[1]}`;$("resultPanel").innerHTML=`<div class="resultMark">${cfg[0]}</div>${result.matchedSelection?`<p>的中買い目 <strong>${result.matchedSelection.join("-")}</strong> / ${esc(result.betCategory||"")}</p>`:""}${result.officialPayout?`<p>公式配当 <strong>${Number(result.officialPayout).toLocaleString()}円</strong></p>`:""}<p class="muted">確認 ${formatTime(result.checkedAt)}</p>`}
function renderSaved(){const all=loadSnapshots(localStorage);$("savedCount").textContent=`${all.length}件`;$("savedList").innerHTML=all.length?all.slice(0,8).map((s,i)=>`<article class="savedItem"><h3>${esc(s.targetRace.venueName)} ${s.targetRace.raceNo}R</h3><p>${formatDate(s.targetRace.date)} / ${formatTime(s.createdAt)} ${s.result?`/ ${resultLabel(s.result.resultStatus)}`:""}</p><button data-saved="${i}">詳細を見る</button></article>`).join(""):'<p class="empty">保存した予想はまだありません。</p>';$("savedList").querySelectorAll("[data-saved]").forEach(b=>b.onclick=()=>{const s=all[Number(b.dataset.saved)];openSavedDetail(s)})}
function deadlineOf(r){return String(r?.deadline||r?.scheduledStart||"")}
function raceStatus(r){const t=parseTime(r.date,deadlineOf(r));if(!t)return{label:"未発走",className:""};const diff=t-Date.now();if(diff<=0)return{label:"終了",className:"danger"};if(diff<=15*60000)return{label:"締切間近",className:"warning"};return{label:"未発走",className:""}}
function meetingNextDeadline(m){const nums=raceNumbersOf(m),races=(nums.length?nums:Array.from({length:12},(_,i)=>i+1)).map(n=>raceFrom(m,n)),timed=races.map(r=>({r,t:parseTime(r.date,deadlineOf(r))})).filter(x=>x.t).sort((a,b)=>a.t-b.t),next=timed.find(x=>x.t>Date.now());if(next)return`次締切 ${next.r.raceNo}R ${deadlineOf(next.r)}`;return timed.length?"本日終了":"締切確認中"}
function meetingTimeBand(m){const nums=raceNumbersOf(m),races=(nums.length?nums:Array.from({length:12},(_,i)=>i+1)).map(n=>raceFrom(m,n)),minutes=races.map(r=>timeMinutes(deadlineOf(r))).filter(Number.isFinite);if(!minutes.length)return{key:"day",label:"デイ"};const first=Math.min(...minutes),last=Math.max(...minutes);if(last>=21*60)return{key:"midnight",label:"ミッド"};if(last>=18*60)return{key:"night",label:"ナイター"};if(first<10*60)return{key:"morning",label:"モーニング"};return{key:"day",label:"デイ"}}
function timeMinutes(value){const m=String(value||"").match(/(\d{1,2}):(\d{2})/);return m?Number(m[1])*60+Number(m[2]):NaN}
function parseTime(date,time){const m=String(time||"").match(/(\d{1,2}):(\d{2})/);if(!m)return null;const d=String(date).replace(/\D/g,"");return new Date(`${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}T${m[1].padStart(2,"0")}:${m[2]}:00+09:00`).getTime()}
function venueCode(m){return String(m.venueCode||m.code||VENUE_CODES[m.venueName]||"").padStart(2,"0")}function getCard(m){return m.discovery?.links?.raceCards?.[0]||m.discovery?.links?.other?.[0]}function getOdds(m){return m.discovery?.links?.odds?.[0]}
function displayParticipantRole(p){const order=Number(p?.lineOrder);if(!Number.isFinite(order))return p?.role||"";return order===1?"先頭":order===2?"番手":`${order}番手`}
function lineText(ps,raceCategory="standard",abilities=[]){if(raceCategory==="girls"){const ranked=[...(abilities||[])].filter(hasUsableGirlsStartPower).sort((a,b)=>Number(b.startPower)-Number(a.startPower)||Number(a.number)-Number(b.number)).slice(0,3);return ranked.length>=2?`固定ラインなし / 主導権候補 ${ranked.map(x=>`${x.number}番`).join(" ＞ ")}`:"固定ラインなし / 主導権候補 判定保留"}const groups=new Map();for(const p of ps||[]){const key=p.lineId||p.line||`solo-${p.number}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p)}const rows=[...groups.values()].map(members=>members.sort((a,b)=>(Number(a.lineOrder)||99)-(Number(b.lineOrder)||99)||Number(a.number)-Number(b.number)).map((p,index)=>{const order=Number(p.lineOrder)||index+1,role=order===1?"先頭":order===2?"番手":`${order}番手`;return `${p.number}(${role})`}).join("－"));return rows.join("　/　")||"公式ライン未取得"}
function metas(rows){return rows.map(([a,b])=>`<div class="meta"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join("")}function formatDate(v){const d=String(v||"").replace(/\D/g,"");return d.length===8?`${d.slice(0,4)}/${d.slice(4,6)}/${d.slice(6,8)}`:v||"-"}function formatTime(v){try{return new Intl.DateTimeFormat("ja-JP",{month:"numeric",day:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(v))}catch{return"-"}}function resultLabel(v){return({hit:"的中",miss:"不的中",refund:"返還",cancelled:"中止"})[v]||v}function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
